from common import *
SEMIO=''
semio=[
('normal','La fonction normale : contenir une brèche sans obstruer la circulation', '''<p>Une hémostase efficace doit former un caillot là où il est utile et maintenir le reste de la circulation ouvert. Les plaquettes, les facteurs plasmatiques et la surface des cellules participent à cette localisation. La thrombine transforme le fibrinogène en fibrine ; les mécanismes anticoagulants et la fibrinolyse limitent ensuite l’extension et la persistance de la réaction. L’endothélium est une interface active de cet équilibre.</p><p>Cette organisation explique la question clinique centrale : le sang peut-il encore assurer la perfusion tout en arrêtant un saignement ? Dans une CIVD, ces fonctions peuvent se dégrader simultanément. La normalité ne se résume donc pas à un chiffre de plaquettes ou de fibrinogène ; elle suppose une régulation adaptée au lieu, au temps et au besoin.</p>''',['NORMAL-HEMO','REVIEW25','ISTH25']),
('signs','Les signes : observer saignement et ischémie ensemble', '''<p>Le saignement aux muqueuses, aux sites de ponction ou sur un champ opératoire peut révéler une hémostase consommée ou une fibrinolyse excessive. Le purpura et les ecchymoses rendent une partie du problème visible, sans en déterminer à eux seuls la cause. L’absence d’un saignement spectaculaire ne rassure pas sur la microcirculation.</p><p>La cyanose acrale, une nécrose périphérique, l’oligurie, l’hypoxémie et les troubles de conscience peuvent accompagner une atteinte d’organe. Leur interprétation reste multifactorielle : le choc, l’infection, les traitements et une maladie préexistante peuvent intervenir. Les signes sont recherchés ensemble, datés et répétés ; aucune photographie ni observation isolée ne donne une probabilité certaine de CIVD.</p>''',['REVIEW25','ISTH25']),
('mechanisms','Le mécanisme : consommer en formant des thrombi', '''<p>L’activation diffuse de la coagulation produit de la thrombine et de la fibrine dans la circulation. Les plaquettes participent aux dépôts et peuvent être consommées. Les réserves de facteurs diminuent si leur utilisation dépasse leur renouvellement. Un patient peut alors développer des obstructions microvasculaires tout en disposant de moins de moyens pour arrêter une hémorragie.</p><p>La fibrinolyse modifie ce profil. Si elle est trop freinée, la persistance des dépôts favorise l’obstruction ; si elle devient excessive, la dégradation du matériel hémostatique peut aggraver le saignement. Le contexte causal et le moment de l’observation déterminent leur combinaison. Cette dynamique explique pourquoi un médicament utile dans une situation peut être inapproprié dans une autre.</p>''',['REVIEW25','ISTH25','TXA']),
('examination','L’examen : choisir une mesure pour une fonction', '''<p>La numération plaquettaire mesure une concentration de cellules ou fragments circulants, mais pas toutes leurs fonctions. Le PT explore un temps de coagulation ; le fibrinogène renseigne un substrat de la fibrine ; les D-dimères témoignent de la dégradation de fibrine réticulée. Ces informations sont complémentaires et doivent garder leurs unités et leurs références.</p><p>L’examen du frottis répond à une question morphologique. La recherche d’une souffrance rénale, respiratoire, circulatoire ou neurologique répond à une question d’organe. La recherche du foyer infectieux ou d’une cause tumorale répond à une question causale. Demander plusieurs examens n’a d’intérêt que si chaque résultat peut être relié à une hypothèse ou à une décision.</p>''',['HUG-LAB','ISTH25','REVIEW25']),
('interpretation','L’interprétation : le temps fait partie de la valeur', '''<p>Un résultat obtenu après transfusion de plaquettes, apport de fibrinogène ou administration d’un anticoagulant ne décrit pas l’état initial. La date et l’heure du prélèvement, les produits et les doses reçus doivent être rapprochés du résultat. Une hausse transitoire d’un paramètre après substitution ne prouve pas que la consommation est arrêtée.</p><p>Comparer les tendances dans une méthode cohérente évite de confondre une différence technique avec une aggravation clinique. Le score ISTH utilise le PT en secondes au-delà du témoin, alors que le SIC utilise le PT-INR. Les D-dimères sont rapportés à une limite supérieure de méthode. L’arithmétique correcte ne compense pas une unité ou une population incorrecte.</p>''',['ISTH25','HUG-LAB','FIB','HUG-TRANS']),
('differentials','Les diagnostics concurrents : distinguer sans exclure les associations', '''<p>Des schizocytes orientent vers une fragmentation des hématies, mais peuvent se rencontrer dans plusieurs processus. Une microangiopathie thrombotique exige une démarche spécifique et parfois urgente ; sa présence ne se déduit pas d’une image de cours. Une atteinte rénale ne permet pas d’écarter arbitrairement le purpura thrombotique thrombocytopénique.</p><p>Un défaut de synthèse hépatique, une perte sanguine importante, une dilution ou l’effet d’un médicament peuvent produire une partie des anomalies. Ils peuvent aussi coexister avec une CIVD. La bonne question n’est donc pas toujours de choisir un seul nom : il faut déterminer quels mécanismes sont présents et lesquels changent la conduite immédiate.</p>''',['REVIEW25','RMS','TRAUMA','HNF','FIB']),
('urgency','L’urgence : reconnaître une décision qui ne peut attendre', '''<p>Une hémorragie menaçante, un choc, un purpura rapidement extensif, une détresse respiratoire ou une altération neurologique imposent une évaluation urgente. Le score aide à structurer le diagnostic mais ne doit pas retarder le soutien des organes ni le traitement d’une cause évidente. Une phase précoce peut ne pas remplir les critères d’une CIVD manifeste.</p><p>La filière dépend du contexte : infection et contrôle d’un foyer, traumatisme, complication obstétricale ou urgence hématologique. Une suspicion de leucémie promyélocytaire ne suit pas un simple calendrier de recontrôle ambulatoire. Les responsabilités et les délais d’action doivent être explicites, tandis que les prescriptions restent liées au protocole spécialisé.</p>''',['ISTH25','SSC26','APL','PPH-CH','TRAUMA']),
('limits','Les limites : ce qu’un signe ou un score ne certifie pas', '''<p>Une numération ne mesure pas toute la fonction plaquettaire ; un PT ne mesure pas à lui seul toute l’hémostase ; un D-dimère élevé n’est pas spécifique de CIVD. Un fibrinogène encore normal peut refléter un équilibre temporaire entre synthèse et consommation. Une valeur obtenue après traitement doit être interprétée comme telle.</p><p>Les sources lues ne permettent pas de donner une fréquence suisse de chaque signe ni une sensibilité individuelle fiable pour cette catégorie de cours. Les images du normal illustrent des structures ; elles ne prouvent ni n’excluent une maladie. La couverture des rubriques pédagogiques ne constitue pas une certification médicale humaine du contenu.</p>''',['ISTH25','REVIEW25','BLOOD-IMAGE','SEM-IMAGE']),
('sources','Les sources : relier la décision à sa population', '''<p>Le cadre biologique et diagnostique s’appuie sur la communication ISTH2025, la revue2025 et le laboratoire suisse. Les décisions thérapeutiques sont confrontées aux fiches suisses datées et aux recommandations de chaque contexte. Les textes de sepsis, de traumatisme, de péripartum et de leucémie promyélocytaire ne sont pas des protocoles interchangeables.</p><p>Le seuil de fibrinogène du score ne devient pas une cible de traitement. Une recommandation prophylactique ne devient pas une indication curative. Les articles ou images non accessibles ne sont pas comptés comme lus ; les réemplois de lectures antérieures sont attribués. Les liens ci-dessous donnent des références directes, avec les limites détaillées dans la fenêtre des sources.</p>''',['ISTH25','REVIEW25','HUG-LAB','FIB','AT','HNF','TXA','SSC26'])]
for marker,title,body,sources in semio:
 heading=f'<h3>{title}</h3>' if marker!='normal' else '<h3>Pour la leçon : quelle est la sémiologie fondamentale et analytique ?</h3><h4>'+title+'</h4>'
 SEMIO+=f'<section class="ilot" id="d65-semio-{marker}" data-semiology="{marker}">{heading}{body}{refs(*sources)}</section>'
SEMIO+=causal('d65-causal-semio','De la science à la décision',['Régulation hémostatique perturbée','Saignement et/ou souffrance d’organe','Examens datés et cause recherchée','Action adaptée puis réévaluation'],'Les observations restent contextualisées ; aucun signe isolé ne remplace cette démarche.')+refs('REVIEW25','ISTH25')
ANAT='''<h3>La circulation : une interface entre sang et tissus</h3>
<p>Le sang doit rester mobile dans les vaisseaux pour apporter aux tissus ce dont ils ont besoin. L’endothélium tapisse cette interface et participe à la régulation de la coagulation, de l’inflammation et des échanges. Une lésion locale doit déclencher une réponse limitée ; une activation diffuse de cette interface peut modifier les propriétés du sang sur une grande surface.</p>
<p>Dans la CIVD, les dépôts de plaquettes et de fibrine peuvent toucher la microcirculation de plusieurs organes. L’atteinte rénale peut se manifester par une diminution des urines ; l’atteinte pulmonaire par une hypoxémie ; une atteinte cérébrale par une altération de la conscience. Ces associations expliquent ce qu’il faut surveiller, mais ne prouvent pas que chaque signe résulte exclusivement d’un thrombus. L’inflammation, l’état circulatoire et la maladie causale interviennent aussi.</p>
<p>La taille du vaisseau et la localisation du processus déterminent ce qui peut être observé. Un microthrombus n’est pas directement visible à l’examen de la peau ; une cyanose ou une nécrose est une conséquence tissulaire. Un prélèvement sanguin explore des éléments circulants, tandis qu’une image d’organe répond à une autre question. Le raisonnement doit relier les échelles sans prétendre que l’une photographie directement l’autre.</p>
''' + original('sem','d65-science-sem') + '''
<p>La micrographie montre une hématie et un groupe de plaquettes. Elle aide à distinguer des éléments figurés et à comprendre qu’une surface cellulaire participe à l’hémostase. Elle ne montre pas une paroi vasculaire ni une CIVD. Aucun chiffre de concentration, aucune activité plaquettaire et aucun degré d’obstruction ne peuvent être calculés à partir de cette image de préparation.</p>
<p>Cette limite a une conséquence thérapeutique : le traitement doit agir sur la maladie et sur ses conséquences fonctionnelles. Remplacer un facteur peut corriger un déficit mesuré, mais ne retire pas la cause d’activation endothéliale. Soutenir la perfusion peut être nécessaire alors même que le laboratoire montre une amélioration partielle. Les compartiments sanguin, vasculaire et tissulaire doivent rester distingués dans le suivi.</p>
<p>La carte clinique se construit donc avec plusieurs observations : circulation périphérique, respiration, fonction rénale, état neurologique et hémostase. Aucune représentation anatomique inventée n’est utilisée pour simuler une preuve d’organe ; la figure originale sert à comprendre les éléments visibles, et les mécanismes sont expliqués dans le texte.</p>
''' + refs('NORMAL','REVIEW25','ISTH25','SEM-IMAGE')
HIST='''<h3>Du frottis aux dépôts : voir une structure ne suffit pas à nommer une maladie</h3>
<p>Un frottis sanguin étale les cellules sur une lame pour permettre leur observation. La forme et la répartition des hématies, l’aspect des autres éléments et la qualité de la préparation contribuent à l’interprétation. La numération et la morphologie répondent à des questions différentes : une image n’est pas une concentration, et une concentration ne décrit pas toutes les formes cellulaires.</p>
<p>Dans certaines CIVD, la circulation à travers des zones pathologiques peut s’accompagner d’une fragmentation des hématies. Les schizocytes sont alors un indice de destruction mécanique. Ils ne sont pas spécifiques de la CIVD et doivent conduire à considérer une microangiopathie thrombotique ainsi que les autres mécanismes pertinents. Le nombre, la méthode d’évaluation et la cohérence clinique relèvent de l’examen réel du patient.</p>
''' + original('blood','d65-science-blood') + '''
<p>Le champ normal présenté ici est large. On y voit de nombreux disques érythrocytaires et une échelle originale, mais ce grossissement ne permet pas de certifier l’absence de rares anomalies. La légende ne désigne donc aucun schizocyte imaginaire et ne transforme pas cette photographie en image diagnostique de CIVD. Les variations de densité sur la lame ne donnent pas la concentration sanguine du sujet.</p>
<p>La revue2025 rapporte des constatations de dépôts microvasculaires de plaquettes et de fibrine dans des contextes cliniques, autopsiques ou expérimentaux. Ce niveau de preuve décrit une réalité physiopathologique ; il n’impose pas une biopsie à chaque patient suspect de CIVD. Le diagnostic clinique s’appuie sur la cause, les signes et les examens appropriés, avec une attention particulière aux risques des gestes invasifs.</p>
<p>Il faut ainsi distinguer le matériel observé : le frottis montre des éléments circulants ; une coupe tissulaire peut montrer l’architecture et des dépôts ; un dosage décrit un paramètre dans un échantillon. Ces méthodes se complètent, mais elles ne peuvent pas être substituées les unes aux autres. Une micrographie du normal est utile pour apprendre la morphologie tout en restant limitée dans sa portée diagnostique.</p>
<p>La conséquence pratique est simple : décrire ce qui est réellement visible, puis préciser ce qui reste une hypothèse. Cette discipline évite de faire confirmer un diagnostic par une image qui ne le démontre pas et permet de choisir l’examen suivant pour la bonne question.</p>
''' + refs('BLOOD-IMAGE','REVIEW25','RMS','APL')
PHYS='''<h3>Physiologie : produire assez de thrombine, puis limiter la réaction</h3>
<p>La coagulation normale est une succession de réactions enzymatiques organisée sur des surfaces cellulaires. Le complexe du facteur tissulaire et du facteurVII activé initie la réaction. Les complexes ténase et prothrombinase amplifient ensuite la génération de thrombine. Le calcium et les surfaces phospholipidiques participent à cette organisation ; une simple liste de numéros de facteurs ne rend pas compte de cette localisation.</p>
<p>La thrombine transforme le fibrinogène en fibrine et active le facteurXIII, qui stabilise le réseau. Elle renforce aussi la réaction par des boucles d’amplification. Cette puissance explique l’efficacité de l’hémostase à une brèche, mais aussi la gravité d’une activation diffuse lorsqu’elle n’est plus suffisamment contrôlée.</p>
<p>Trois grands mécanismes anticoagulants sont décrits dans la revue : l’antithrombine, le système protéineC–thrombomoduline et l’inhibiteur de la voie du facteur tissulaire. Ils agissent sur des étapes différentes. Leur fonctionnement dépend aussi de l’environnement endothélial. Dans la CIVD, la consommation, la dégradation et l’atteinte de ces surfaces peuvent réduire leur efficacité.</p>
<p>La fibrinolyse contribue à remodeler le réseau de fibrine. Le plasminogène est activé en plasmine ; des activateurs et des inhibiteurs règlent cette réaction. La prédominance d’un frein de fibrinolyse favorise la persistance des dépôts, tandis qu’une activation excessive peut contribuer au saignement. Ces mécanismes ne s’excluent pas dans le temps : leur balance peut changer avec l’évolution de la maladie.</p>
''' + causal('d65-causal-phys','L’équilibre hémostatique normal',['Lésion localisée et activation sur surfaces','Thrombine puis fibrine stabilisée','Freins anticoagulants et fibrinolyse régulée','Caillot utile sans extension diffuse'],'Le schéma représente des relations fonctionnelles, pas une structure anatomique ; la CIVD perturbe leur régulation et leur localisation.') + '''
<p>Un résultat de laboratoire est une observation partielle de cet équilibre. Le fibrinogène peut être produit et consommé simultanément ; les plaquettes peuvent être consommées, remplacées et dysfonctionnelles à des degrés variables. Un chiffre normal n’est donc pas une photographie complète de la régulation. La tendance et le contexte restent nécessaires.</p>
<p>Sur le plan thérapeutique, fournir un substrat, freiner une enzyme et inhiber la fibrinolyse sont trois actions différentes. Le mécanisme seul ne prouve pas qu’un médicament améliore le résultat clinique. Il faut aussi une indication, une population étudiée, une balance de risques et une surveillance. C’est précisément pourquoi les produits de l’onglet pharmacologie ne sont pas proposés comme une série à administrer à tous les patients.</p>
''' + refs('NORMAL-HEMO','REVIEW25','ISTH25','FIB','AT','HNF','TXA')
BIO='''<h3>Biochimie : substrat, enzyme, inhibiteur et produit de dégradation</h3>
<p>Le fibrinogène est une protéine soluble qui sert de substrat à la formation de fibrine. La thrombine est une enzyme qui permet cette transformation ; le facteurXIII activé contribue à stabiliser le réseau. Un dosage de fibrinogène et un dosage ou marqueur d’activité de coagulation ne décrivent donc pas la même étape. Une quantité de substrat disponible ne suffit pas à expliquer la vitesse de sa consommation.</p>
<p>La plasmine participe à la dégradation du réseau. Les D-dimères sont liés à la dégradation de fibrine réticulée ; ils ne sont pas une mesure directe de la masse de caillot dans tous les organes. Une augmentation signifie qu’un processus de formation et de dégradation de fibrine doit être interprété, mais ne désigne pas à elle seule la CIVD. Le contexte biologique et clinique reste indispensable.</p>
<p>Les mécanismes de régulation comprennent des inhibiteurs et des cofacteurs. L’antithrombine agit sur plusieurs enzymes ; la protéineC activée réduit l’activité de certains cofacteurs ; l’inhibiteur de la voie du facteur tissulaire limite l’initiation. Un déficit d’un frein peut favoriser l’activation, mais sa mesure ne démontre pas automatiquement le bénéfice d’une substitution. La preuve thérapeutique ne se déduit pas uniquement de la logique biochimique.</p>
''' + causal('d65-causal-bio','Des molécules aux paramètres mesurés',['Fibrinogène soluble : substrat','Thrombine puis fibrine réticulée','Dégradation de fibrine : D-dimères','Résultats interprétés avec cause et méthode'],'Le diagramme distingue les étapes ; un résultat élevé ou bas ne résume pas toute la balance hémostatique.') + '''
<p>Les unités traduisent ce que l’on mesure. Une concentration en g/L rapporte une masse à un volume ; un temps en secondes mesure une durée ; un INR est un rapport normalisé utilisé dans des contextes précis ; un multiple de limite supérieure est un rapport sans unité. Ces grandeurs ne doivent pas être additionnées directement : le score convertit d’abord chacune en une catégorie de points.</p>
<p>La conversion100mg/dL =1g/L s’explique en deux étapes :100mg représentent0,1g et1dL représente0,1L ; le rapport0,1g/0,1L vaut1g/L. Le chiffre100 n’a donc pas le même sens lorsqu’on change les unités. De même, une solution de20mg/mL relie une masse à un volume d’administration, pas à la concentration que l’on obtiendra automatiquement dans le sang.</p>
<p>Après administration de fibrinogène, le résultat dépend notamment de la situation clinique et de la consommation ; il doit être mesuré et réévalué. Un calcul de volume permet de préparer une quantité prescrite, mais ne prédit pas à lui seul la réponse biologique. La distinction entre calcul exact et décision clinique doit rester explicite dans toute fenêtre pédagogique.</p>
''' + refs('REVIEW25','ISTH25','FIB','HUG-LAB')
IMMUNO='''<h3>Immunologie : quand la réponse protectrice devient diffuse</h3>
<p>L’inflammation et la coagulation ne fonctionnent pas indépendamment. Une réponse locale peut contribuer à contenir une agression et à préserver l’intégrité tissulaire. La revue2025 décrit ce lien entre immunité innée, cellules circulantes et endothélium. Lorsque l’agression est intense ou diffuse, les mêmes mécanismes peuvent participer à une activation intravasculaire excessive.</p>
<p>Les neutrophiles peuvent libérer des réseaux extracellulaires, appelés NETs, composés notamment d’ADN et de protéines. Les histones et d’autres constituants peuvent interagir avec les cellules et les voies de coagulation. La revue décrit des effets sur l’intégrité endothéliale, l’exposition de surfaces procoagulantes et l’amplification de la génération de thrombine. Ces résultats éclairent les mécanismes ; ils ne fournissent pas un test de routine universel à demander devant chaque suspicion de CIVD.</p>
<p>Les plaquettes participent elles aussi aux interactions inflammatoires. L’activation des cellules et de l’endothélium peut modifier l’exposition des phospholipides, la libération de médiateurs et l’assemblage des complexes de coagulation. Les freins anticoagulants peuvent être altérés par la consommation, la dégradation ou la perturbation de leur environnement. La diffusion de l’activation transforme une réponse localement utile en processus délétère.</p>
''' + causal('d65-causal-immuno','Inflammation et coagulation se renforcent',['Agression et réponse immunitaire innée','Activation des cellules et de l’endothélium','Coagulation amplifiée et freins perturbés','Microthrombose et inflammation des organes'],'Relations mécanistiques issues de la revue ; elles ne valident pas à elles seules un médicament ciblant ces voies.') + '''
<p>Cette perspective explique pourquoi traiter l’infection ou une autre cause reste essentiel. Fournir des plaquettes ou du fibrinogène peut répondre à une conséquence immédiate sans arrêter le signal qui entretient la consommation. Le soutien des organes et le contrôle de la cause doivent donc accompagner les décisions hémostatiques, plutôt que venir seulement après la normalisation du laboratoire.</p>
<p>La protéineC activée existe comme élément physiologique de régulation. Cela ne signifie pas que l’ancien médicament recombinant correspondant reste une option thérapeutique : les essais et le retrait du produit sont une question clinique distincte. De même, des résultats d’analyses de sous-groupes sur l’antithrombine ou la thrombomoduline ne doivent pas être transformés en preuve générale pour toutes les personnes atteintes de CIVD.</p>
<p>La lecture critique conserve ainsi trois niveaux : mécanisme biologique plausible, effet mesuré dans une étude et bénéfice clinique démontré dans une population. Confondre ces niveaux produit des prescriptions séduisantes mais insuffisamment justifiées. Le cours relie les mécanismes aux observations tout en maintenant cette limite.</p>
''' + refs('REVIEW25','SSC26','AT','ISTH25')
TABS=[('semio','Sémiologie fondamentale et analytique',SEMIO),('anat','Anatomie',ANAT),('histo','Histologie',HIST),('phys','Physiologie',PHYS),('bio','Biochimie et hémostase',BIO),('immuno','Immunologie',IMMUNO)]
LINKS={
 'semio':['Relier saignement et souffrance d’organe aux mécanismes possibles.','Comparer des mesures datées, avec unités et références cohérentes.','Agir sur l’urgence et la cause ; ne pas attendre un score complet.'],
 'anat':['Les conséquences dépendent des organes et de la microcirculation atteints.','Un prélèvement sanguin et une exploration d’organe répondent à des questions distinctes.','Traiter la cause et soutenir les organes en parallèle des corrections biologiques.'],
 'histo':['Une fragmentation érythrocytaire est un indice, pas un diagnostic unique.','Décrire le frottis réel et rechercher les diagnostics concurrents.','La décision spécialisée ne se fonde pas sur une photographie normale de cours.'],
 'phys':['Thrombose et saignement peuvent résulter du même dérèglement.','Le profil et sa tendance renseignent davantage qu’un paramètre isolé.','Substitution, anticoagulation et antifibrinolyse ont des buts différents.'],
 'bio':['Substrat, enzyme et produit de dégradation ne sont pas interchangeables.','Vérifier unités, méthode et calcul avant d’attribuer les points du score.','Calculer un volume sans confondre ce calcul avec l’indication ou la réponse.'],
 'immuno':['La réponse inflammatoire peut entretenir une activation diffuse.','Une hypothèse mécanistique ne devient pas automatiquement un test de routine.','Contrôler la cause ; ne pas prescrire sur une plausibilité biologique seule.']}
def sciences():
 s='<div class="panel" id="pS" hidden><div class="sci-bar ui" role="tablist">'
 for k,t,_ in TABS:s+=f'<button id="d65-tab-{k}" role="tab" aria-selected="{str(k=="semio").lower()}" aria-controls="d65-s-{k}" data-s="d65-s-{k}">{t}</button>'
 s+='</div><div class="chap-body sci-body">'
 for k,t,b in TABS:
  bridge='<div class="key">'+''.join(f'<p><b>{a}</b> {v}</p>' for a,v in zip(['Science → clinique.','Science → examen.','Science → traitement.'],LINKS[k]))+'<p><b>À retenir.</b> Relier mécanisme, mesure et décision sans dépasser la preuve.</p></div>'
  body=b if k=='semio' else f'<section class="ilot" id="d65-s-{k}-cours">{b}</section>';hide='' if k=='semio' else ' hidden'
  s+=f'<div class="sci" id="d65-s-{k}" role="tabpanel" aria-labelledby="d65-tab-{k}"{hide}>{body}{bridge}<button class="pareto-btn ui" data-k="pareto-d65-{k}">▲ Loi de Pareto — {t}</button></div>'
 return s+'</div><div class="pager ui"><button class="prev">← Partie précédente</button><span></span><button class="next">Partie suivante →</button></div></div>'
